<?php
namespace App\Domain\AI\Knowledge\Services;use App\Domain\AI\Agents\Services\AiLifecycleAuthorization;use App\Domain\AI\Knowledge\Contracts\KnowledgeChunker;use App\Domain\AI\Knowledge\Data\KnowledgeContentData;use App\Domain\AI\Knowledge\Enums\{KnowledgeIndexStatus,KnowledgeSourceStatus};use App\Domain\AI\Knowledge\Exceptions\ArchivedKnowledgeSourceException;use App\Domain\AI\Knowledge\Models\{KnowledgeIndex,KnowledgeSource,KnowledgeSourceVersion};use App\Models\User;use Illuminate\Support\Facades\DB;
final class BuildKnowledgeIndexService
{
 public function __construct(private AiLifecycleAuthorization$auth,private KnowledgeChunker$chunker){}
 public function build(int$indexId):KnowledgeIndex{try{return DB::transaction(function()use($indexId){$probe=KnowledgeIndex::query()->findOrFail($indexId);$actor=User::query()->findOrFail($probe->requested_by_user_id);$a=$this->auth->authorize($actor);$source=KnowledgeSource::query()->lockForUpdate()->findOrFail($probe->knowledge_source_id);$version=KnowledgeSourceVersion::query()->lockForUpdate()->findOrFail($probe->knowledge_source_version_id);$index=KnowledgeIndex::query()->lockForUpdate()->findOrFail($indexId);if($index->status===KnowledgeIndexStatus::Ready&&hash_equals($index->content_checksum,$version->checksum))return$index;if($source->status!==KnowledgeSourceStatus::Active)throw new ArchivedKnowledgeSourceException('Archived knowledge cannot be indexed.');if((int)$version->knowledge_source_id!==(int)$source->id||(int)$index->knowledge_source_id!==(int)$source->id||(int)$index->knowledge_source_version_id!==(int)$version->id)throw new \UnexpectedValueException('Invalid knowledge index structure.');if(!hash_equals($version->checksum,$index->content_checksum))throw new \UnexpectedValueException('Knowledge checksum mismatch.');$data=KnowledgeContentData::fromPersisted($version->content);$chunks=$this->chunker->chunks($data);if($chunks===[])throw new \InvalidArgumentException('Knowledge content produced no chunks.');$index->markProcessing($a);$index->clearChunks($a);foreach($chunks as$chunk)$index->createChunk($a,$chunk);$index->markReady($a,count($chunks));return$index->fresh();});}catch(\Throwable$e){$code=$e instanceof ArchivedKnowledgeSourceException?'source_archived':($e instanceof \InvalidArgumentException?'invalid_content':($e instanceof \UnexpectedValueException?'checksum_mismatch':'indexing_failed'));$this->failSafely($indexId,$code);if($code==='indexing_failed')throw$e;return KnowledgeIndex::query()->findOrFail($indexId);}}
 private function failSafely(int$id,string$code):void{DB::transaction(function()use($id,$code){$index=KnowledgeIndex::query()->lockForUpdate()->findOrFail($id);if($index->status===KnowledgeIndexStatus::Ready)return;$actor=User::query()->findOrFail($index->requested_by_user_id);$a=$this->auth->authorize($actor);$index->markFailed($a,$code);});}
}
